<?php
require __DIR__.'/../app/bootstrap.php';$adminId=require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'reviewed');if(!in_array($status,['reviewed','dismissed'],true))$status='reviewed';$pdo->prepare('UPDATE travel_match_reports SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$status,$adminId,$id]);flash('success','Travel Match report updated.');redirect('admin/match-reports.php');}
$stmt=$pdo->query('SELECT r.*,reporter.display_name reporter_name,reported.display_name reported_name,reported.email reported_email,msg.body reported_message FROM travel_match_reports r JOIN users reporter ON reporter.id=r.reporter_user_id JOIN users reported ON reported.id=r.reported_user_id LEFT JOIN travel_match_messages msg ON msg.id=r.reported_message_id ORDER BY CASE r.status WHEN "open" THEN 0 ELSE 1 END,r.created_at DESC LIMIT 250');$rows=$stmt->fetchAll();$success=flash('success');$title='Travel Match Reports';require __DIR__.'/../partials/header.php';
?>
<section class="dashboard"><div class="shell"><div class="dashboard-head"><div><div class="eyebrow">Admin · Travel Matching</div><h1>Safety Reports</h1><p class="muted">Reports are automatically paired with a user-level block. Review here for account-level action if needed.</p></div><a class="button secondary" href="<?=e(app_url('admin/index.php'))?>">Admin Home</a></div><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><div class="dashboard-card"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Status</th><th>Reported</th><th>Reporter</th><th>Reason</th><th>Reported message</th><th>Details</th><th>Date</th><th>Review</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8">No Travel Match reports.</td></tr><?php else:?><?php foreach($rows as $r):?><tr><td><span class="status-pill"><?=e($r['status'])?></span></td><td><strong><?=e($r['reported_name']?:'User #'.$r['reported_user_id'])?></strong><br><span class="muted small"><?=e($r['reported_email'])?></span></td><td><?=e($r['reporter_name']?:'User #'.$r['reporter_user_id'])?></td><td><?=e(str_replace('_',' ',$r['reason']))?></td><td><?php if($r['reported_message_id']):?><span class="muted small">Message #<?=(int)$r['reported_message_id']?></span><br><?=e($r['reported_message']??'[message unavailable]')?><?php else:?><span class="muted small">Profile-level report</span><?php endif;?></td><td><?=e($r['details']??'')?></td><td><?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></td><td><?php if($r['status']==='open'):?><form method="post" class="review-actions"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="button small secondary" name="status" value="reviewed">Reviewed</button><button class="button small text-button" name="status" value="dismissed">Dismiss</button></form><?php else:?><span class="muted small"><?=e($r['reviewed_at']??'')?></span><?php endif;?></td></tr><?php endforeach;?><?php endif;?></tbody></table></div></div></div></section><?php require __DIR__.'/../partials/footer.php';?>
